// Some portions generated by Codex
package org.eclipse.rdf4j.common.iteration;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.NoSuchElementException;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;

class IterationWrapperInterruptionTest {

	@Test
	void interruptedNextRetainsTypedCauseAndClosesExactlyOnce() {
		AtomicInteger closes = new AtomicInteger();
		try (var iteration = iteration(closes, null, null)) {
			assertThat(iteration.hasNext()).isTrue();
			Thread.currentThread().interrupt();
			NoSuchElementException failure = assertThrows(NoSuchElementException.class, iteration::next);
			assertThat(failure).hasMessage("The iteration has been interrupted.")
					.hasCauseInstanceOf(InterruptedException.class);
			assertThat(Thread.currentThread().isInterrupted()).isTrue();
		} finally {
			Thread.interrupted();
		}
		assertThat(closes).hasValue(1);
	}

	@Test
	void interruptionPreservesCleanupFailure() {
		AtomicInteger closes = new AtomicInteger();
		IllegalStateException cleanup = new IllegalStateException("delegate close failed");
		try (var iteration = iteration(closes, null, cleanup)) {
			Thread.currentThread().interrupt();
			assertThat(assertThrows(IllegalStateException.class, iteration::next)).isSameAs(cleanup);
			assertThat(Thread.currentThread().isInterrupted()).isTrue();
		} finally {
			Thread.interrupted();
		}
		assertThat(closes).hasValue(1);
	}

	@Test
	void ordinaryNoSuchElementFailureIsNotReclassifiedByItsMessage() {
		AtomicInteger closes = new AtomicInteger();
		NoSuchElementException original = new NoSuchElementException("The iteration has been interrupted.");
		try (var iteration = iteration(closes, original, null)) {
			assertThat(assertThrows(NoSuchElementException.class, iteration::next)).isSameAs(original).hasNoCause();
		}
		assertThat(closes).hasValue(1);
	}

	private static IterationWrapper<Integer> iteration(AtomicInteger closes, RuntimeException nextFailure,
			RuntimeException closeFailure) {
		return new IterationWrapper<>(new CloseableIteration<Integer>() {
			@Override
			public boolean hasNext() {
				return true;
			}

			@Override
			public Integer next() {
				if (nextFailure != null) {
					throw nextFailure;
				}
				return 1;
			}

			@Override
			public void close() {
				closes.incrementAndGet();
				if (closeFailure != null) {
					throw closeFailure;
				}
			}
		}) {
		};
	}
}
